/bin/zsh -lc "python3.12 -B -c 'from solution import TTLCache

def check(name, fn):
 try:
  fn(); print(\"PASS:\",name)
 except Exception as e: print(\"FAIL:\",name,type(e).__name__,str(e))

def invalid_capacity():
 for v in [True,False,0,-1,1.5,\"2\",None]:
  try: TTLCache(v,lambda:0)
  except ValueError: continue
  raise AssertionError(\"accepted \"+repr(v))
check(\"capacity validation\",invalid_capacity)

def scenario(kind):
 t=[0]; c=TTLCache(2,lambda:t[0])
 if kind==\"boundary\":
  c.set(\"a\",1,1); t[0]=1; assert c.get(\"a\",\"missing\")==\"missing\"
 elif kind==\"len cleanup\":
  c.set(\"a\",1,1); t[0]=2; assert len(c)==0
 elif kind==\"get cleanup\":
  c.set(\"a\",1,1); t[0]=2; c.get(\"missing\"); assert not c.items
 elif kind==\"set cleanup\":
  c.set(\"live\",1,10); c.set(\"expired\",2,1); t[0]=2; c.set(\"new\",3,10); assert c.get(\"live\")==1
 elif kind==\"zero TTL\":
  c.set(\"a\",1,10); c.set(\"a\",2,0); assert c.get(\"a\",\"missing\")==\"missing\"
 elif kind==\"replacement\":
  c.set(\"a\",1,10); c.set(\"b\",2,10); c.set(\"b\",3,20); assert c.get(\"a\")==1
 elif kind==\"get recency\":
  c.set(\"a\",1,10); c.set(\"b\",2,10); c.get(\"a\"); c.set(\"c\",3,10); assert c.get(\"a\")==1 and c.get(\"b\") is None
 elif kind==\"set recency\":
  c=TTLCache(3,lambda:0); c.set(\"a\",1,10); c.set(\"b\",2,10); c.set(\"a\",3,10); c.set(\"c\",4,10); c.set(\"d\",5,10); assert c.get(\"a\")==3 and c.get(\"b\") is None
for kind in [\"boundary\",\"len cleanup\",\"get cleanup\",\"set cleanup\",\"zero TTL\",\"replacement\",\"get recency\",\"set recency\"]: check(kind,lambda:scenario(kind))
for ttl in [True,False,-1,float(\"nan\"),float(\"inf\"),-float(\"inf\"),\"1\",None]:
 c=TTLCache(1,lambda:0); c.set(\"a\",1,10); before=dict(c.items)
 try: c.set(\"b\",2,ttl); result=\"accepted\"
 except Exception as e: result=type(e).__name__
 print(\"TTL\",repr(ttl),result,\"contents unchanged:\",c.items==before)
for value in [None,0,False,\"\"]:
 c=TTLCache(1,lambda:0); c.set(\"a\",value,10); print(\"falsy\",repr(value),\"preserved:\",c.get(\"a\",object()) is value)
'"
